description:
We were missing to clear `<div>`s when several `console.log()` events trigger at the same time, animation with several events was also confusing since the delayed fade-out animation was noisy, instead, this clears `<div>`s properly and fades-out instead of moving and fading elements:

``````
// !preview r2d3 data=c(0.3, 0.6, 0.8, 0.95, 0.40, 0.20)
//
// r2d3: https://rstudio.github.io/r2d3
//

var barHeight = Math.ceil(height / data.length);

svg.selectAll('rect')
  .data(data)
  .enter().append('rect')
    .attr('width', function(d) { return d * width; })
    .attr('height', barHeight)
    .attr('y', function(d, i) { return i * barHeight; })
    .attr('fill', 'steelblue')
    .on("mouseover", function(d){ console.log("Value: " + d); });
``````

![console-log-anim](https://user-images.githubusercontent.com/3478847/40397920-3151fe60-5dea-11e8-8436-8515abde14b5.gif)

Subset of https://github.com/rstudio/r2d3/pull/17

```js
// !preview r2d3 data=c(0.3, 0.6, 0.8, 0.95, 0.40, 0.20), container = "svg", dependencies = "~/jetpack.js"
//
// r2d3: https://rstudio.github.io/r2d3
//

var { svg, margin, height, width } = d3.conventions({
  sel: svg,
  totalWidth: width,
  totalHeight: height,
  margin: { top: 60, bottom: 60 }
});

var barHeight = Math.ceil(height / data.length);

svg.selectAll('rect')
  .data(data)
  .enter().append('rect')
    .attr('width', function(d) { return d * width; })
    .attr('height', barHeight)
    .attr('y', function(d, i) { return i * barHeight; })
    .attr('fill', 'steelblue');

```

Adds support to include extensions with ease, say `d3-jetpack`, `rickshaw`, etc. Couple examples:

## Jetpack

```js
// !preview r2d3 data=c(0.3, 0.6, 0.8, 0.95, 0.40, 0.20), dependencies = d3_extension("d3-jetpack")

var { svg, margin, height, width } = d3.conventions({
  sel: svg,
  totalWidth: width,
  totalHeight: height,
  margin: { top: 60, bottom: 60 }
});

var barHeight = Math.ceil(height / data.length);

svg.selectAll('rect')
  .data(data)
  .enter().append('rect')
    .attr('width', function(d) { return d * width; })
    .attr('height', barHeight)
    .attr('y', function(d, i) { return i * barHeight; })
    .attr('fill', 'steelblue');
```

