## Rickshaw

```js
// !preview r2d3 data = dplyr::transmute(Orange, x = age, y = circumference), container = "div", dependencies = d3_extension("rickshaw"), d3_version = 3, options = list(type = "bar")

var graph = new Rickshaw.Graph({
  element: div.node(),
  width: width,
  height: height,
  renderer: options.type,
  series: [{
    color: 'orange',
    data: data
  }]
});

graph.render();
```

